def get_invoice(invoice_id: UUID, claims: TokenClaims = Depends(verify_jwt), db: Session = Depends(get_db)):
    invoice = db.query(Invoice).filter(
        Invoice.id == invoice_id,
        Invoice.tenant_id == claims.tenant_id  # Forzado desde el claim verificado
    ).first()
    if not invoice:
        raise HTTPException(status_code=404, detail="Not found")
    return invoice
